// Read-only lifecycle inventory. Hashes and scalar tokens never retain source
// arrays or GPU objects; token tables use weak keys. No render/ensure/envelope.
async () => {
 const A=ATLAS,R=A.renderer,G=GA,MAX_RECORDS=2300,MAX_VIEWS=20000;
 if(R.records.length>MAX_RECORDS)throw Error('Source inventory record bound exceeded');
 const tokens=globalThis.__muenSourceTokens||(globalThis.__muenSourceTokens={views:new WeakMap(),buffers:new WeakMap(),nextView:1,nextBuffer:1});
 const token=(map,key,counter)=>{if(!map.has(key))map.set(key,tokens[counter]++);return map.get(key);};
 const cache=new WeakMap(),ledger=new Map(),views=new Set();
 const hex=b=>Array.from(new Uint8Array(b),v=>v.toString(16).padStart(2,'0')).join('');
 const hash=async a=>{if(!cache.has(a))cache.set(a,crypto.subtle.digest('SHA-256',new Uint8Array(a.buffer,a.byteOffset,a.byteLength)).then(hex));return await cache.get(a);};
 async function descriptor(a,owner,identity){
  views.add(a);if(views.size>MAX_VIEWS)throw Error('Source inventory typed-view bound exceeded');
  if(!ledger.has(a.buffer))ledger.set(a.buffer,{bytes:a.buffer.byteLength,owners:new Set()});
  ledger.get(a.buffer).owners.add(owner);
  const d={type:a.constructor.name,length:a.length,bytes:a.byteLength,sha256:await hash(a)};
  if(identity){d.viewToken=token(tokens.views,a,'nextView');d.bufferToken=token(tokens.buffers,a.buffer,'nextBuffer');d.byteOffset=a.byteOffset;}
  return d;
 }
 async function metadata(v,path,arrays,identity,ancestors){
  if(ArrayBuffer.isView(v)){arrays[path]=await descriptor(v,path,identity);return{typedArray:path};}
  if(v===null||typeof v!=='object')return typeof v==='function'||v===undefined?null:v;
  if(v instanceof ArrayBuffer)throw Error('Unclassified raw source backing at '+path);
  if(ancestors.has(v))throw Error('Unexpected cyclic source metadata at '+path);
  ancestors.add(v);let out;
  if(Array.isArray(v)){out=[];for(let i=0;i<v.length;i++)out.push(await metadata(v[i],path+'/'+i,arrays,identity,ancestors));}
  else if(v instanceof Map||v instanceof Set)throw Error('Source metadata collection needs explicit review: '+path);
  else{out={};for(const k of Object.keys(v).sort())if(v[k]!==undefined&&typeof v[k]!=='function')out[k]=await metadata(v[k],path+'/'+k,arrays,identity,ancestors);}
  ancestors.delete(v);return out;
 }
 const records=[];
 for(const r of R.records){
  if(!['overview','muenzuka'].includes(r.pack))throw Error('Unexpected native owner '+r.pack);
  const row={id:r.data.id,pack:r.pack,arrays:{}};
  row.metadata=await metadata(r.data,r.pack+':'+r.data.id,row.arrays,r.pack==='overview',new WeakSet());records.push(row);
 }
 records.sort((a,b)=>a.pack.localeCompare(b.pack)||a.id.localeCompare(b.id));
 const dataArrays={},seen=new WeakSet();
 async function dataViews(v,path){
  if(ArrayBuffer.isView(v)){dataArrays[path]=await descriptor(v,path,true);return;}
  if(!v||typeof v!=='object'||seen.has(v))return;seen.add(v);
  if(v instanceof ArrayBuffer)throw Error('Unclassified raw data backing at '+path);
  if(v instanceof Map){for(const [k,x]of v)await dataViews(x,path+'/map:'+String(k));return;}
  if(v instanceof Set){let i=0;for(const x of v)await dataViews(x,path+'/set:'+i++);return;}
  for(const k of Object.keys(v).sort())await dataViews(v[k],path+'/'+k);
 }
 await dataViews(A.data,'data');
 const privatePrototypes=[],prototypeResidency=[];
 const edge=G.MUENZUKA_EDGE,culling=G.MUENZUKA_EDGE_CULLING;
 if(!!edge!==!!culling)throw Error('Partial Muenzuka extension installation');
 if(edge){
  for(const variant of [0,1]){
   const id='overview016:muenzuka|forestLeaf|vegetation|I'+(variant?9:7)+':muenzuka-west-edge';
   const cold=R.records.find(r=>r.pack==='overview'&&r.data.id===id),p=edge.prototype(variant),again=edge.prototype(variant);
   // The boot's cold record already owns this exact far view. A getter that
   // newly created a missing prototype would fail instead of filling a gap.
   if(!cold||cold.data.vertices!==p.far||p!==again)throw Error('Main-thread prototype was not already retained by public boot');
   for(const lod of ['near','far']){
    const a=p[lod],key='privateMuenzuka:'+variant+':'+lod;
    privatePrototypes.push({id:key,variant,lod,array:await descriptor(a,key,true)});
    prototypeResidency.push({id:key,residentInGPU:R.geometryRefs.has(a),publicArrayOwners:R.records.filter(r=>r.pack==='overview'&&[r.data.vertices,r.data.farVertices].includes(a)).map(r=>r.data.id).sort()});
   }
  }
 }
 const remaining=G.MUENZUKA_WOODLAND,remainingCulling=G.MUENZUKA_WOODLAND_CULLING;
 if(!!remaining!==!!remainingCulling)throw Error('Partial remaining Muenzuka extension installation');
 const remainingNativeIDs=new Set(['-22:6:1','-22:7:0','-21:6:1','-22:8:0','-21:7:0',
  '-22:6:0','-22:7:1','-22:8:1','-21:7:1','-21:6:0'].map(k=>'muenzuka:trees:'+k+':leaf'));
 const remainingColdIDs=new Set(['overview016:muenzuka|forestLeaf|vegetation|I7','overview016:muenzuka|forestLeaf|vegetation|I9']);
 const targetNative=/^muenzuka:trees:-23:[678]:[01]:leaf$/;
 const targetCold=/^overview016:muenzuka\|forestLeaf\|vegetation\|I[79]:muenzuka-west-edge$/;
 function actualOutside(m,s){
  let maximum=-Infinity,points=0;const b=m.instances,c=s.center;
  const arrays=m.farVertices&&m.farVertices!==m.vertices?[m.vertices,m.farVertices]:[m.vertices];
  for(const a of arrays)for(let j=0;j<a.length;j+=9){
   const x=a[j],y=a[j+1],z=a[j+2],t=Math.max(0,Math.min(1,(y-4)/18)),w=t*t*(3-2*t)*.16;
   for(let i=0;i<b.length;i+=16)for(const sx of[-1,1])for(const sz of[-1,1]){
    const X=x+sx*w,Z=z+sz*w*.5;
    maximum=Math.max(maximum,Math.hypot(b[i]*X+b[i+4]*y+b[i+8]*Z+b[i+12]-c.x,
     b[i+1]*X+b[i+5]*y+b[i+9]*Z+b[i+13]-c.y,b[i+2]*X+b[i+6]*y+b[i+10]*Z+b[i+14]-c.z)-s.radius);points++;
   }
  }
  return{maximumOutside:maximum,points,tolerance:1e-7};
 }
 const spheres=[];
 for(const r of R.records){
  const western=targetNative.test(r.data.id)||targetCold.test(r.data.id);
  const rest=remainingNativeIDs.has(r.data.id)||remainingColdIDs.has(r.data.id);
  const oldEligible=!!culling&&!!culling.eligible(r.data),newEligible=!!remainingCulling&&!!remainingCulling.eligible(r.data);
  if(oldEligible!==!!(culling&&western)||newEligible!==!!(remainingCulling&&rest))throw Error('Unexpected local culling eligibility: '+r.data.id);
  const eligible=oldEligible||newEligible;
  if(!western&&!rest)continue;
  const s=r.item?.mesh.boundingSphere;
  if(s&&(!Number.isFinite(s.radius)||s.radius<=0||!s.center.toArray().every(Number.isFinite)))throw Error('Invalid actual mesh sphere');
  spheres.push({id:r.data.id,pack:r.pack,family:western?'acceptedWestern':'remainingWoodland',eligible,resident:!!r.item,wanted:r.wanted,level:r.level,
   sphere:s?{center:s.center.toArray(),radius:s.radius}:null,
   actualWindEnvelope:eligible&&s?actualOutside(r.data,s):null});
 }
 spheres.sort((a,b)=>a.id.localeCompare(b.id));
 const ledgerRows=[...ledger.values()].map(x=>({bytes:x.bytes,owners:[...x.owners].sort()})).sort((a,b)=>a.owners[0].localeCompare(b.owners[0]));
 const native=R.packs.get('muenzuka');let nativeGeometrySHA256=null;
 if(native){const encoder=new TextEncoder(),parts=[];let length=0;
  for(const m of native.meshes){const header=encoder.encode(JSON.stringify([m.id,m.material,m.center,m.radius,m.lod]));parts.push(header);length+=header.byteLength;
   for(const key of ['vertices','farVertices','instances','instanceColors','index'])if(m[key]){const a=m[key],bytes=new Uint8Array(a.buffer,a.byteOffset,a.byteLength);parts.push(bytes);length+=bytes.byteLength;}}
  const joined=new Uint8Array(length);let offset=0;for(const p of parts){joined.set(p,offset);offset+=p.byteLength;}
  nativeGeometrySHA256=await crypto.subtle.digest('SHA-256',joined).then(hex);
 }
 const cold=records.filter(r=>r.pack==='overview'&&r.metadata.owner==='muenzuka');
 return{records,dataArrays,privatePrototypes,prototypeResidency,spheres,nativeGeometrySHA256,
  remainingAvailable:!!remaining,remainingCullingAvailable:!!remainingCulling,
  cullingAvailable:!!culling,privateGetterAlreadyRetained:!!edge,
  counts:{publicRecords:records.filter(r=>r.pack==='overview').length,nativeRecords:records.filter(r=>r.pack==='muenzuka').length,
   muenzukaColdRecords:cold.length,coldOrdinaryTrees:R.records.filter(r=>r.pack==='overview'&&r.data.owner==='muenzuka'&&r.data.material==='forestLeaf').reduce((n,r)=>n+r.data.instances.length/16,0),
   sourceViews:views.size,uniqueBackings:ledger.size,uniqueBackingBytes:ledgerRows.reduce((n,x)=>n+x.bytes,0)},
  backingLedger:ledgerRows,
  readOnlyMeaning:'No draw, finish, ensure, envelope, forced garbage collection or strong source/GPU references retained by probe. Managed native ownership can be proven clear; JavaScript collection timing is not asserted.'};
}

// Synchronous, bounded, observation-only managed GPU attribution. Event
// listeners record scalar dispose timestamps; weak keys retain no mesh/array.
// No draw/finish/ensure/trim or production function override is performed.
(function(){
 // This factory lives outside each inventory activation: persistent event
 // listeners close over weak/scalar state and scalar IDs, never its local maps
 // of source arrays or GPU objects.
 function disposeListener(S,kind,id,recordId,geometryId){return()=>{
  if(S.disposeEvents.length>=10000)throw Error('Dispose inventory bound exceeded');
  S.disposeEvents.push({kind,id,recordId,geometryId,atSeconds:performance.now()/1000,
   phase:globalThis.__muenWoodlandInventoryPhase||null,
   lastObservedGeometryOwners:(S.geometryOwners.get(geometryId)||[]).map(o=>({...o}))});
 };}
 return label => {
 const A=ATLAS,R=A.renderer,E=R.engine,MAX_RECORDS=2300,MAX_GEOMETRIES=1024,MAX_EVENTS=10000;
 if(R.records.length>MAX_RECORDS||R.geometryRefs.size>MAX_GEOMETRIES)throw Error('Resident inventory bound exceeded');
 const S=globalThis.__muenWoodlandResidentTokens||(globalThis.__muenWoodlandResidentTokens={
  views:new WeakMap(),attributes:new WeakMap(),observedGeometry:new WeakSet(),observedMesh:new WeakSet(),
  nextView:1,nextAttribute:1,disposeEvents:[],geometryOwners:new Map()});
 const token=(map,o,next)=>{if(!map.has(o))map.set(o,S[next]++);return map.get(o);};
 const desc=a=>a?{viewToken:token(S.views,a,'nextView'),type:a.constructor.name,bytes:a.byteLength,
  length:a.length,byteOffset:a.byteOffset}:null;
 const now=performance.now()/1000,rows=[],owners=new Map(),attributes=new Map(),sourceViews=new Map();
 const addAttribute=(a,owner,role)=>{
  if(!a)return null;const key=a.isInterleavedBufferAttribute?a.data:a;
  if(!attributes.has(key))attributes.set(key,{attributeToken:token(S.attributes,key,'nextAttribute'),
    array:desc(key.array),roles:new Set(),owners:new Set()});
  const q=attributes.get(key);q.roles.add(role);q.owners.add(owner);sourceViews.set(key.array,q.array);
  return q.attributeToken;
 };
 globalThis.__muenWoodlandInventoryPhase=label;
 for(const r of R.records){if(!r.item)continue;
  const m=r.data,mesh=r.item.mesh,g=mesh.geometry,pack=r.pack||'overview';
  const row={id:m.id,pack,owner:m.owner||null,component:m.component||null,material:m.material||null,
   level:r.level,wanted:!!r.wanted,objectVisible:!!mesh.visible,shadowOnly:!!r.shadowOnly,lastUsedSeconds:r.lastUsed,
   unusedAgeSeconds:now-r.lastUsed,geometryId:g.id,meshId:mesh.id,sourceArray:desc(r.array),
   instanceBytes:m.instances?m.instances.byteLength+(m.instanceColors?.byteLength||0):0,
   instanceMatrix:desc(m.instances),instanceColors:desc(m.instanceColors),attributeTokens:[]};
  for(const[name,a]of Object.entries(g.attributes))row.attributeTokens.push(addAttribute(a,pack+':'+m.id,'geometry/'+name));
  if(g.index)row.attributeTokens.push(addAttribute(g.index,pack+':'+m.id,'geometry/index'));
  if(mesh.isInstancedMesh){row.attributeTokens.push(addAttribute(mesh.instanceMatrix,pack+':'+m.id,'instanceMatrix'));
   if(mesh.instanceColor)row.attributeTokens.push(addAttribute(mesh.instanceColor,pack+':'+m.id,'instanceColor'));}
  row.attributeTokens=[...new Set(row.attributeTokens)];rows.push(row);
  if(!owners.has(r.array))owners.set(r.array,[]);owners.get(r.array).push({id:m.id,pack,level:r.level,wanted:!!r.wanted,lastUsedSeconds:r.lastUsed});
  if(mesh.isInstancedMesh&&!S.observedMesh.has(mesh)){S.observedMesh.add(mesh);const id=mesh.id,rid=m.id,gid=g.id;
   mesh.addEventListener('dispose',disposeListener(S,'instancedMesh',id,rid,gid));}
 }
 const geometries=[];
 for(const[a,value]of R.geometryRefs){
  const list=(owners.get(a)||[]).sort((a,b)=>a.id.localeCompare(b.id));
  if(list.length!==value.refs)throw Error('Managed geometry reference/owner mismatch '+value.geo.id);
  if(!list.length)throw Error('Unowned managed geometry '+value.geo.id);
  S.geometryOwners.set(value.geo.id,list.map(o=>({...o})));
  geometries.push({geometryId:value.geo.id,bytes:value.bytes,refs:value.refs,array:desc(a),owners:list});
  if(!S.observedGeometry.has(value.geo)){S.observedGeometry.add(value.geo);const id=value.geo.id;
   value.geo.addEventListener('dispose',disposeListener(S,'geometry',id,null,id));}
 }
 const attributeRows=[...attributes.values()].map(q=>({...q,roles:[...q.roles].sort(),owners:[...q.owners].sort()}));
 const uniqueAttributeBytes=attributeRows.reduce((n,q)=>n+q.array.bytes,0),instanceCountedBytes=rows.reduce((n,q)=>n+q.instanceBytes,0);
 const geometryCountedBytes=geometries.reduce((n,q)=>n+q.bytes,0),reconciledResidentBytes=geometryCountedBytes+instanceCountedBytes;
 if(reconciledResidentBytes!==R.residentBytes)throw Error('Managed geometry+instance byte ledger does not reconcile');
 // For these sources no special renderer-only attributes are allowed to hide
 // outside the ordinary managed count. CPU alias bytes are reported separately.
 if(uniqueAttributeBytes!==R.residentBytes)throw Error('Actual unique GPU attribute-object ledger does not reconcile');
 const unownedSceneGeometry=[];
 const managedIDs=new Set(geometries.map(x=>x.geometryId));
 R.scene.traverse(o=>{if(o.isMesh&&o.geometry&&!managedIDs.has(o.geometry.id))unownedSceneGeometry.push({
  meshId:o.id,name:o.name||null,geometryId:o.geometry.id,owner:o.userData?.owner||null,visible:!!o.visible});});
 rows.sort((a,b)=>a.pack.localeCompare(b.pack)||a.id.localeCompare(b.id));geometries.sort((a,b)=>a.geometryId-b.geometryId);
 return{label,atSeconds:now,drawnFrames:A.state.drawnFrames,pose:{eye:A.rig.eye.slice(),target:A.rig.target.slice(),fov:A.rig.fov},
  settings:{clock:A.state.clock,quality:A.state.quality,rendererQuality:R.quality,weather:A.state.weather,lighting:A.state.lighting,
   ao:A.state.ao,motion:A.state.motion,bloom:A.state.bloom,reflections:A.state.reflections,characters:A.state.characters,labels:A.state.labels},
  stats:{...R.info().stats},engineMemory:{...E.info.memory},residentAttributeBytes:R.residentBytes,
  limit:{records:MAX_RECORDS,geometries:MAX_GEOMETRIES,disposeEvents:MAX_EVENTS},complete:true,
  residentRows:rows,managedGeometries:geometries,uniqueGPUAttributeObjects:attributeRows,
  uniqueGPUAttributeBytes:uniqueAttributeBytes,uniqueCPUSourceViewBytes:[...sourceViews.values()].reduce((n,a)=>n+a.bytes,0),
  byteReconciliation:{geometryCountedBytes,instanceCountedBytes,reconciledResidentBytes,exact:true},
  sceneGeometryOutsideRecordOwnership:unownedSceneGeometry,disposeEvents:S.disposeEvents.map(x=>({...x})),
  inferenceLimits:'Managed record/geometry ownership and actual attribute object bytes are exhaustive here. Engine memory.geometries may also count sky/sign/post/shadow resources. Disposal timestamps do not by themselves prove a caller or the historical A/B cause. No JavaScript GC or physical VRAM assertion.'};
 };
})()

// Read-only frame/actual-draw observer for a fixed production camera route.
// Temporary mesh callbacks invoke their originals and are restored on cleanup.
// This does not call render/finish/ensure, assign LOD, or alter any model bound.
spec => {
 const A=ATLAS,R=A.renderer,ids=new Set(spec.targetIDs),MAX_FRAMES=512,MAX_DRAWS=20000;
 if(globalThis.__muenWoodlandLOD)throw Error('LOD observer collision');
 const snapshots=[],observed=new WeakSet(),restores=[],sphereTokens=new WeakMap();let nextSphere=1;
 const S={active:false,frames:snapshots,pendingDraws:[],allDraws:[],watching:false,routeSegment:null,
  targetIDs:spec.targetIDs,legResults:[],maxFrames:MAX_FRAMES,failed:null};
 function attach(){for(const r of R.records)if(r.pack==='muenzuka'&&ids.has(r.data.id)&&r.item?.mesh&&!observed.has(r.item.mesh)){
  const mesh=r.item.mesh,original=mesh.onBeforeRender;observed.add(mesh);
  mesh.onBeforeRender=function(...args){
   if(S.pendingDraws.length+S.allDraws.length>=MAX_DRAWS)throw Error('LOD actual-draw bound exceeded');
   const row={frame:A.state.drawnFrames+1,id:r.data.id,level:r.level,instances:r.data.instances.length/16,
    atMs:performance.now(),segment:S.routeSegment};S.pendingDraws.push(row);S.allDraws.push(row);original?.apply(this,args);
  };
  restores.push(()=>{mesh.onBeforeRender=original});
 }}
 function capture(label){attach();const n=A.state.drawnFrames;
  if(snapshots.length>=MAX_FRAMES)throw Error('LOD frame bound exceeded');
  if(snapshots.at(-1)?.drawnFrames===n)return snapshots.at(-1);
  const records=R.records.filter(r=>r.pack==='muenzuka'&&ids.has(r.data.id)).map(r=>{
   const m=r.data,s=r.item?.mesh.boundingSphere;
   if(s&&!sphereTokens.has(s))sphereTokens.set(s,nextSphere++);
   const family=spec.remainingIDs.includes(m.id)?'remainingWoodland':'acceptedWestern';
   const expectedCulling=family==='acceptedWestern'||!!GA.MUENZUKA_WOODLAND_CULLING;
   return{id:m.id,family,instances:m.instances.length/16,level:r.level,wanted:!!r.wanted,
    resident:!!r.item,meshId:r.item?.mesh.id||null,objectVisible:!!r.item?.mesh.visible,distance:r.distance,
    sphereToken:s?sphereTokens.get(s):null,sphere:s?{center:s.center.toArray(),radius:s.radius}:null,
    expectedCulling};
  });
  const row={label,segment:S.routeSegment,drawnFrames:n,atMs:performance.now(),transitioning:!!A.rig.transition,
   eye:A.rig.eye.slice(),target:A.rig.target.slice(),focus:A.state.focus,
   required:[...A.stream.required],records,
   actualDraws:S.pendingDraws.filter(d=>d.frame===n).map(d=>({...d})),stats:{...R.info().stats}};
  S.pendingDraws=[];snapshots.push(row);return row;
 }
 function watch(){if(!S.active){S.watching=false;return;}
  try{capture('continuous production transition');if(!A.rig.transition){S.active=false;S.watching=false;return;}}
  catch(e){S.failed=String(e.stack||e);S.active=false;S.watching=false;return;}
  requestAnimationFrame(watch);
 }
 S.begin=label=>{if(S.active)throw Error('Previous LOD leg still active');S.routeSegment=label;attach();S.active=true;S.watching=true;requestAnimationFrame(watch)};
 S.capture=capture;
 S.result=()=>({frames:snapshots.map(x=>({...x})),allDraws:S.allDraws.map(x=>({...x})),failed:S.failed,
  active:S.active,observerMeshCount:restores.length,maxFrames:MAX_FRAMES,maxDraws:MAX_DRAWS,
  meaning:'Actual production RAF transition frames and mesh submission callbacks, not hardware FPS. No forced LOD or sphere change.'});
 S.cleanup=()=>{S.active=false;const n=restores.length;for(const f of restores)f();restores.length=0;
  snapshots.length=0;S.pendingDraws.length=0;S.allDraws.length=0;
  return{restoredCallbacks:n,strongMeshReferencesReleased:true,productionFunctionsReplaced:false}};
 globalThis.__muenWoodlandLOD=S;attach();return{targetRecords:ids.size,observerMeshCount:restores.length};
}

label => {
 const A=ATLAS,R=A.renderer,E=R.engine,limit=1024,owners=new Map();
 for(const r of R.records) if(r.item&&r.array){
   if(!owners.has(r.array))owners.set(r.array,[]);
   owners.get(r.array).push({id:r.data.id,pack:r.pack,level:r.level,wanted:!!r.wanted});
 }
 const geometry=[];let n=0;
 for(const [a,value]of R.geometryRefs){
   if(n++>=limit)break;
   geometry.push({id:value.geo.id,bytes:value.bytes,refs:value.refs,
     owners:(owners.get(a)||[]).sort((a,b)=>a.id.localeCompare(b.id))});
 }
 const programs=E.info.programs.slice(0,limit).map(p=>({cacheKey:p.cacheKey,id:p.id,
   usedTimes:p.usedTimes,type:p.type,name:p.name})).sort((a,b)=>a.cacheKey.localeCompare(b.cacheKey));
 const wanted=R.records.filter(r=>r.wanted&&r.item?.mesh.visible).map(r=>({id:r.data.id,pack:r.pack,level:r.level})).sort((a,b)=>a.id.localeCompare(b.id));
 return {label,at:performance.now(),testPause:!!globalThis.ATLAS_TEST_PAUSE,
   snapshot:R.captureDiagnostics(label),diagnosticCounters:{...R.info().diagnostics.counters},stats:{...R.info().stats},
   rig:{eye:A.rig.eye.slice(),target:A.rig.target.slice(),fov:A.rig.fov,mode:A.rig.mode},
   drawnFrames:A.state.drawnFrames,clock:A.state.clock,view:A.state.view,
   detailNeighbors:A.state.detailNeighbors.slice(),rendererPackIds:[...R.packs.keys()].sort(),recordMapNativeIds:[...R.recordMap.values()].filter(r=>r.pack!=='overview').map(r=>r.data.id).sort(),visibleNativePacks:[...new Set(R.records.filter(r=>r.wanted&&r.item?.mesh.visible&&r.pack!=='overview').map(r=>r.pack))],quality:A.state.quality,rendererQuality:R.quality,cutaway:A.state.cutaway,
   memory:{...E.info.memory},residentAttributeBytes:R.residentBytes,
   detailIds:R.records.filter(r=>r.pack!=='overview').map(r=>r.data.id).sort(),
   publicIds:R.records.filter(r=>r.pack==='overview').map(r=>r.data.id).sort(),wanted,
   geometryInventory:{limit,count:R.geometryRefs.size,complete:R.geometryRefs.size<=limit,entries:geometry},
   programInventory:{limit,count:E.info.programs.length,complete:E.info.programs.length<=limit,entries:programs},
   contextLost:E.getContext().isContextLost(),stream:A.stream.info()};
}
